      position: relative;
      z-index: 1;
      display: grid;
      gap: 32px;
      align-items: center;
      max-width: 1120px;
      margin: 0 auto;
    }
    #j2-hero .j2-hero-text { min-width: 0; }
    #j2-hero .j2-hero-tag {
      display: inline-block;
      margin: 0 0 16px;
      padding: 6px 14px;
      border-radius: 999px;
      background: var(--j2-accent, #FFD23F);
      color: #0F1020;
      font-weight: 700;
      font-size: 0.875rem;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }
    #j2-hero h1 {
      margin: 0 0 12px;
      font-family: var(--j2-font-heading, 'Space Grotesk', system-ui, sans-serif);
      font-size: clamp(2.75rem, 13vw, 5.5rem);
      line-height: 1;
      font-weight: 700;
      letter-spacing: -0.02em;
      overflow-wrap: anywhere;
      background: linear-gradient(90deg, #FF4F8B, #FFD23F);
      -webkit-background-clip: text;
      background-clip: text;
      -webkit-text-fill-color: transparent;
      color: #FF4F8B;
    }
    #j2-hero .j2-hero-college {
      margin: 0 0 8px;
      font-family: var(--j2-font-heading, 'Space Grotesk', system-ui, sans-serif);
      font-size: clamp(1.125rem, 4.5vw, 1.625rem);
      font-weight: 500;
      color: var(--j2-text, #F5F6FF);
    }
    #j2-hero .j2-hero-dates {
      margin: 0 0 28px;
      font-size: clamp(1.125rem, 4.5vw, 1.375rem);
      font-weight: 600;
      color: var(--j2-accent, #FFD23F);
    }
    #j2-hero .j2-hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
    }
    #j2-hero .j2-hero-actions a { max-width: 100%; text-align: center; }
    #j2-hero .j2-photo-placeholder {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 100%;
      max-width: 100%;
      aspect-ratio: 4 / 3;
      border-radius: var(--j2-radius, 16px);
      border: 2px dashed rgba(255, 210, 63, 0.6);
      background: linear-gradient(135deg, rgba(108, 92, 231, 0.35), rgba(255, 79, 139, 0.25));
      color: var(--j2-muted, #B8BCE0);
      font-size: 0.9375rem;
      text-align: center;
      padding: 16px;
    }
    @media (min-width: 900px) {
      #j2-hero { padding: 96px 32px 104px; }
      #j2-hero .j2-hero-inner { grid-template-columns: 1.1fr 0.9fr; gap: 56px; }
    }
  </style>
  <div class="j2-hero-inner">
    <div class="j2-hero-text">
      <p class="j2-hero-tag">College tech fest</p>
      <h1 id="j2-hero-title">Spark 2026</h1>
      <p class="j2-hero-college">Northfield College of Engineering, Pune</p>
      <p class="j2-hero-dates">14 to 16 February 2027</p>
