        <a class="j2-btn" href="#j2-register">Register for an event</a>
        <a class="j2-btn j2-btn-secondary" href="#j2-schedule">See the schedule</a>
      </div>
    </div>
    <div class="j2-photo-placeholder" role="img" aria-label="Photo placeholder for Spark 2026">Photo coming soon</div>
  </div>
</section>
